begin;
create table if not exists public.legal_official_sources(id uuid primary key default gen_random_uuid(),label text not null,url text not null unique,document_type text not null,source_entity text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.legal_update_runs(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.legal_official_sources(id),actor_id uuid references auth.users(id),status text not null check(status in('running','complete','partial','failed')),summary jsonb not null default '{}',created_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.legal_update_candidates(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.legal_official_sources(id),run_id uuid references public.legal_update_runs(id),file_url text not null,title text not null,status text not null default 'pending' check(status in('pending','processing','accepted','failed','rejected')),document_id uuid references public.documents(id),review jsonb not null default '{}',error text,created_at timestamptz not null default now(),unique(source_id,file_url));
create table if not exists public.legal_document_events(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id),kind text not null check(kind in('publication','version','reviewed_change')),fingerprint text not null,description text not null,source_url text not null,created_at timestamptz not null default now(),unique(document_id,kind,fingerprint));
create table if not exists public.legal_source_follows(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),document_id uuid references public.documents(id),search jsonb,label text not null,fingerprint text not null,paused boolean not null default false,created_at timestamptz not null default now(),check((document_id is not null and search is null)or(document_id is null and search is not null)),unique(owner_id,fingerprint));
create table if not exists public.legal_follow_notifications(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),follow_id uuid not null references public.legal_source_follows(id)on delete cascade,event_id uuid not null references public.legal_document_events(id),read_at timestamptz,created_at timestamptz not null default now(),unique(follow_id,event_id));
do $$ declare t text;begin foreach t in array array['legal_official_sources','legal_update_runs','legal_update_candidates','legal_document_events','legal_source_follows','legal_follow_notifications']loop execute format('alter table public.%I enable row level security',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
do $$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='legal_source_follows' and policyname='personal_follows')then execute $policy$create policy personal_follows on public.legal_source_follows for all to authenticated using(owner_id=auth.uid())with check(owner_id=auth.uid())$policy$;end if;end $$;
do $$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='legal_follow_notifications' and policyname='personal_notifications')then execute $policy$create policy personal_notifications on public.legal_follow_notifications for select to authenticated using(owner_id=auth.uid())$policy$;end if;end $$;
do $$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='legal_follow_notifications' and policyname='personal_notifications_read')then execute $policy$create policy personal_notifications_read on public.legal_follow_notifications for update to authenticated using(owner_id=auth.uid())with check(owner_id=auth.uid())$policy$;end if;end $$;
do $$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='legal_document_events' and policyname='accessible_document_events')then execute $policy$create policy accessible_document_events on public.legal_document_events for select to authenticated using(exists(select 1 from documents d where d.id=document_id and d.es_institucional=true))$policy$;end if;end $$;
grant select,insert,update,delete on public.legal_source_follows to authenticated;
grant select on public.legal_follow_notifications to authenticated;
grant update(read_at) on public.legal_follow_notifications to authenticated;
grant select on public.legal_document_events to authenticated;
create index if not exists follow_notifications_owner on public.legal_follow_notifications(owner_id,created_at desc);
create index if not exists update_candidates_state on public.legal_update_candidates(status,created_at desc);
commit;
